#!/usr/bin/env python3
"""Translate pinned source registrations and additional font outlines (not oracle output).

Run with uv run --no-project python <script> <mathjax-go module directory>.
"""
import json
import pathlib
import re
import sys

source = pathlib.Path(sys.argv[1]) / "internal"
target = pathlib.Path(__file__).resolve().parents[1] / "src"
header = """// Copyright (c) 2017-2022 The MathJax Consortium
// SPDX-License-Identifier: Apache-2.0
// Source-derived from pinned mathjax-go 94d80186bfd7; MathJax 3.2.2.
// Generated by tools/translate-font-bindings.py; see licenses/.
"""
text = (source / "tex/source_tables_base_maps.go").read_text()
bindings = re.findall(r'Name: "([^"]+)", Value: mjSourceList\{"(MathFont|SetFont)", "([^"]*)"\}', text)
assert len(bindings) == 54, len(bindings)
out = [header]
for method in ["MathFont", "SetFont"]:
    out.append(f'pub(super) fn {"wrapper" if method == "MathFont" else "declaration"}(name: &str) -> Option<&\'static str> {{\n    Some(match name {{\n')
    for name, handler, variant in bindings:
        if handler == method:
            out.append(f'        {json.dumps(name)} => {json.dumps(variant)},\n')
    out.append('        _ => return None,\n    })\n}\n')
(target / "font_bindings.rs").write_text(''.join(out))

out = [header, 'use super::*;\n']
files = ["fraktur_bold", "script_bold", "sans_serif_bold", "sans_serif_italic",
         "sans_serif_bold_italic", "tex_calligraphic_bold", "tex_oldstyle"]
for name in files:
    text = (source / f"font/data_{name}_gen.go").read_text()
    out.append(f'pub(super) static {name.upper()}: &[(u32, GlyphData, f64, &str, f64)] = &[\n')
    entries = re.findall(r'^\s*(0x[0-9A-Fa-f]+):\s*\{Metrics: Metrics\{([^}]*)\}(.*)\},?$', text, re.M)
    assert entries or name == "script_bold", name
    for code, metrics, extra in entries:
        fields = dict(re.findall(r'(\w+): ([^,}]+)', metrics))
        assert set(fields) <= {'Height', 'Depth', 'Width', 'ItalicCorrection', 'Skew', 'HasItalicCorrection', 'HasSkew'}, fields
        strings = dict(re.findall(r'(Path|Content): ("(?:[^"\\]|\\.)*")', extra))
        values = [str(float(fields.get(key, 0))) for key in ['Height','Depth','Width','ItalicCorrection','Skew']]
        h, d, w, ic, sk = values
        out.append(f'    ({code}, GlyphData {{ height: {h}, depth: {d}, width: {w}, path: {strings.get("Path", chr(34)*2)} }}, {ic}, {strings.get("Content", chr(34)*2)}, {sk}),\n')
    out.append('];\n')
(target / "alias_font_glyphs.rs").write_text(''.join(out))
